/* AH-22 · Textos editorials i guia didàctica humana revisats el 05-11-2026.
 * No s'inferix un desplegament a partir de l'existència del codi. Fonts públiques al costat de cada cas. */
const link = (url, text) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${text}</a>`;
const sources = {
  ine: 'https://www.ine.es/prensa/censo_2021_jun.pdf',
  masoveria: 'https://www.diba.cat/ca/web/hua/masoveria',
  rural: 'https://oficinac.es/es/informes-c/desarrollo-territorial-oportunidades-y-desafios-en-los-ambitos-rurales',
  relleu: 'https://www.mapa.gob.es/es/desarrollo-rural/temas/relevo-generacional/medidas-pac'
};
const section = (tag, title, ...paragraphs) => `<${tag}>${title}</${tag}>\n      ${paragraphs.map(p => `<p>${p}</p>`).join('\n      ')}`;
const subSection = (title, ...paragraphs) => `<h4>${title}</h4>\n      ${paragraphs.map(p => `<p>${p}</p>`).join('\n      ')}`;

const housing = {
  ca: [
    'Habitatge', 'Cases per a viure al poble tot l’any', 'Un espai de contacte directe entre qui té una casa i qui busca fer vida al poble. Els casos següents són usos possibles, no anuncis d’habitatges disponibles.',
    ['Obrir portes tancades', 'Mantindre el <strong>poble viu</strong> demana posar en contacte els <strong>propietaris</strong> de <strong>cases o pisos tancats</strong> amb qui busca <strong>lloguer o compra directa</strong>. La <strong>confiança veïnal</strong> ajuda a fer el primer pas: parlar, visitar la casa i publicar una oferta clara, <strong>sense comissions</strong> d’agència en esta plataforma.', 'Una família que vol quedar-se <strong>tot l’any</strong> necessita saber el <strong>preu mensual</strong>, l’<strong>estat de la casa</strong>, la <strong>calefacció</strong> i l’accés als <strong>serveis</strong>. Una persona jove que compra directament necessita <strong>informació contrastable</strong> de l’immoble. El contacte directe no elimina els impostos, les despeses ni les <strong>comprovacions de la compra</strong>.'],
    ['Lloguer anual, casa compartida i masoveria urbana', 'Un <strong>lloguer anual assequible</strong>, una <strong>compra entre particulars</strong> o una <strong>vivenda compartida</strong> poden donar estabilitat a famílies i joves. L’anunci ha de distingir la <strong>residència habitual</strong> d’una <strong>estada de vacances</strong> i explicar preu, durada i condicions amb claredat.', `La <strong>masoveria urbana</strong> pot vincular la <strong>cessió d’ús</strong> d’una <strong>casa buida</strong> a <strong>obres de rehabilitació acordades</strong>. La ${link(sources.masoveria, 'Diputació de Barcelona documenta el model i les seues qüestions pràctiques')}. És una <strong>referència catalana</strong>, no una autorització automàtica per a qualsevol immoble: la <strong>viabilitat tècnica</strong>, el <strong>contracte</strong> i les <strong>normes del lloc</strong> s’han de revisar en cada cas.`],
    ['La paradoxa de les cases tancades', `El ${link(sources.ine, 'Cens d’Habitatges 2021 de l’INE')} situa el <strong>45 % de les vivendes buides</strong> en municipis de <strong>menys de 10.000 habitants</strong>, on vivia el <strong>20,3 % de la població</strong>. És una <strong>dada estatal</strong>, no un <strong>recompte del nostre poble</strong>. <strong>Casa buida</strong> tampoc vol dir casa habitable o disponible.`, 'Als <strong>pobles de muntanya</strong> podem trobar portes tancades mentre una família no troba <strong>lloguer anunciat</strong>: una <strong>herència pendent</strong>, <strong>obres necessàries</strong> o <strong>falta de confiança</strong> poden frenar l’oferta. Són situacions que cal comprovar parlant amb la propietat, sense atribuir-les a cases concretes ni publicar <strong>dades privades</strong>. Fer visible una <strong>oferta real</strong> ajuda més que comptar façanes tancades.']
  ],
  es: ['Vivienda', 'Casas para vivir en el pueblo todo el año', 'Un espacio de contacto directo entre quien tiene una casa y quien busca vivir en el pueblo. Estos casos son usos posibles, no anuncios de viviendas disponibles.',
    ['Abrir puertas cerradas', 'Un <strong>pueblo vivo</strong> necesita conectar a <strong>propietarios de casas cerradas</strong> con familias que buscan <strong>alquiler anual o compra directa</strong>. La confianza vecinal facilita hablar, visitar la casa y publicar una oferta clara, <strong>sin comisiones de agencia</strong> en esta plataforma.', 'Para quedarse todo el año conviene conocer el precio, el estado de la vivienda, la calefacción y los servicios. La compra entre particulares sigue teniendo gastos, impuestos y comprobaciones: el contacto directo no los elimina.'],
    ['Alquiler anual, vivienda compartida y masovería urbana', 'Un <strong>alquiler anual asequible</strong>, la <strong>compra entre particulares</strong> y la <strong>vivienda compartida</strong> pueden dar estabilidad a jóvenes y familias. El anuncio debe diferenciar la residencia habitual de una estancia vacacional y explicar precio, duración y condiciones.', `La <strong>masovería urbana</strong> vincula la cesión de uso a obras de rehabilitación acordadas. La ${link(sources.masoveria, 'Diputación de Barcelona documenta este modelo')}. Es una referencia catalana: cada proyecto necesita comprobar la viabilidad técnica, el contrato y las normas aplicables en su lugar.`],
    ['La paradoja de las casas cerradas', `El ${link(sources.ine, 'Censo de Viviendas 2021 del INE')} sitúa el <strong>45 % de las viviendas vacías</strong> en municipios de menos de 10.000 habitantes, con el 20,3 % de la población. Es un dato estatal, no un recuento del pueblo. <strong>Vacía no significa habitable ni disponible</strong>.`, 'Una herencia pendiente, obras o falta de confianza pueden mantener una casa cerrada mientras faltan alquileres anunciados. Son situaciones que hay que comprobar con la propiedad, sin atribuirlas a casas concretas ni difundir datos privados. Publicar una oferta real ayuda a convertir una puerta cerrada en una posibilidad.']
  ],
  en: ['Housing', 'Homes for year-round village life', 'A place for direct contact between owners and people looking for a village home. These are possible uses, not listings of available homes.',
    ['Opening closed doors', 'A <strong>living village</strong> needs links between owners of <strong>closed houses</strong> and people seeking a <strong>year-round rental or direct purchase</strong>. Neighbourly trust can start a conversation, a visit and a clear listing, with <strong>no agency commission</strong> charged by this platform.', 'Families need to know the monthly rent, condition, heating and local services. A direct purchase still involves checks, taxes and transaction costs; direct contact does not remove them.'],
    ['Annual rentals, shared homes and renovation agreements', 'An <strong>affordable annual rental</strong>, a <strong>private sale</strong> or a <strong>shared home</strong> can help young people and families settle. Listings should distinguish a permanent home from a holiday stay and state the price, duration and conditions clearly.', `<strong>Masoveria urbana</strong> is a model that exchanges an agreed period of use for agreed renovation work. The ${link(sources.masoveria, 'Barcelona Provincial Council explains the model')}. This is a Catalan reference; the technical feasibility, contract and applicable local rules need checking for each project.`],
    ['The closed-house paradox', `The ${link(sources.ine, 'INE 2021 Housing Census')} found <strong>45% of empty homes</strong> in municipalities below 10,000 residents, which held 20.3% of the population. This is a national figure, not a count for this village. <strong>Empty does not mean habitable or available</strong>.`, 'Unresolved inheritance, repairs or a lack of trust can keep a house closed while families find no advertised rentals. Each situation needs checking with its owner, without identifying private homes or publishing personal details. A clear, real listing can open a practical opportunity.']
  ],
  eu: ['Etxebizitza', 'Herrian urte osoan bizitzeko etxeak', 'Jabeen eta herrian bizi nahi duten pertsonen arteko zuzeneko harremanetarako gunea. Adibide hauek erabilera aukerak dira, ez eskuragarri dauden etxeen iragarkiak.',
    ['Itxitako ateak irekitzea', '<strong>Herri bizia</strong> izateko, <strong>etxe itxien jabeak</strong> eta <strong>urte osoko alokairua edo zuzeneko erosketa</strong> bilatzen duten familiak lotu behar dira. Auzokoen konfiantzak elkarrizketa, bisita eta iragarki argia errazten ditu, plataforma honetan <strong>agentzia komisiorik gabe</strong>.', 'Prezioa, etxearen egoera, berokuntza eta zerbitzuak ezagutzea garrantzitsua da. Partikularren arteko erosketak ere zergak, gastuak eta egiaztapenak behar ditu; harreman zuzenak ez ditu kentzen.'],
    ['Urteko alokairua, etxe partekatua eta birgaitzea', '<strong>Urteko alokairu eskuragarriak</strong>, <strong>partikularren arteko salmentak</strong> eta <strong>etxebizitza partekatuak</strong> egonkortasuna eman diezaiekete gazteei eta familiei. Iragarkiak ohiko etxebizitza eta opor egonaldia bereizi behar ditu, prezioa, iraupena eta baldintzak argituz.', `<strong>Masoveria urbana</strong> ereduak etxea erabiltzeko epea eta adostutako birgaitze lanak lotzen ditu. ${link(sources.masoveria, 'Bartzelonako Diputazioak eredua dokumentatzen du')}. Kataluniako erreferentzia da: proiektu bakoitzaren bideragarritasuna, kontratua eta tokiko arauak egiaztatu behar dira.`],
    ['Etxe itxien paradoxa', `${link(sources.ine, 'INEren 2021eko Etxebizitza Erroldaren')} arabera, <strong>etxebizitza hutsen %45</strong> 10.000 biztanletik beherako udalerrietan zeuden, biztanleriaren %20,3 bizi zen tokietan. Estatuko datua da, ez herriko zenbaketa. <strong>Hutsik egoteak ez du esan nahi bizitzeko prest edo eskuragarri dagoenik</strong>.`, 'Ebatzi gabeko oinordetzak, konponketek edo konfiantza faltak etxe bat itxita mantendu dezakete, familiek alokairurik aurkitu ez arren. Egoera bakoitza jabearekin argitu behar da, etxe pribatuak identifikatu edo datu pertsonalak zabaldu gabe. Benetako eskaintza argitaratzea lehen urrats erabilgarria da.']
  ],
  gl: ['Vivenda', 'Casas para vivir na aldea todo o ano', 'Un espazo de contacto directo entre quen ten unha casa e quen busca vivir na aldea. Estes casos son usos posibles, non anuncios de vivendas dispoñibles.',
    ['Abrir portas pechadas', 'Unha <strong>aldea viva</strong> precisa conectar as <strong>persoas propietarias de casas pechadas</strong> con familias que buscan <strong>alugueiro anual ou compra directa</strong>. A confianza veciñal facilita falar, visitar a casa e publicar unha oferta clara, <strong>sen comisións de axencia</strong> nesta plataforma.', 'Para quedar todo o ano cómpre coñecer o prezo, o estado da casa, a calefacción e os servizos. A compra entre particulares segue tendo gastos, impostos e comprobacións: o contacto directo non os elimina.'],
    ['Alugueiro anual, vivenda compartida e masovería urbana', 'Un <strong>alugueiro anual accesible</strong>, a <strong>compra entre particulares</strong> ou unha <strong>vivenda compartida</strong> poden dar estabilidade á mocidade e ás familias. O anuncio debe distinguir a residencia habitual dunha estadía de vacacións e explicar prezo, duración e condicións.', 'A <strong>masovería urbana</strong> vincula a cesión de uso a obras de rehabilitación acordadas. '+link(sources.masoveria, 'A Deputación de Barcelona documenta este modelo')+'. É unha referencia catalá: cada proxecto precisa comprobar a viabilidade técnica, o contrato e as normas aplicables no lugar.'],
    ['A paradoxa das casas pechadas', `O ${link(sources.ine, 'Censo de Vivendas 2021 do INE')} sitúa o <strong>45 % das vivendas baleiras</strong> en municipios de menos de 10.000 habitantes, onde vivía o 20,3 % da poboación. É un dato estatal, non un reconto da aldea. <strong>Baleira non significa habitable nin dispoñible</strong>.`, 'Unha herdanza pendente, obras ou falta de confianza poden manter unha casa pechada mentres faltan alugueiros anunciados. Hai que comprobar cada situación coa propiedade, sen sinalar casas concretas nin difundir datos privados. Publicar unha oferta real pode abrir unha oportunidade.']
  ]
};

const jobs = {
  ca: ['Treball', 'Faena digna i oficis que mantenen viu el poble', 'Connectem qui busca faena amb qui necessita ajuda. Els exemples expliquen necessitats rurals, no vacants confirmades.',
    ['Connectem talent local', 'Trobar <strong>feina digna</strong> i <strong>professionals d’ofici</strong> pot començar prop de casa: un <strong>obrer, electricista, fontaner o cuidadora</strong>, una reparació o una substitució. Publica el lloc, les tasques, l’horari i la remuneració; parlar <strong>sense intermediaris</strong> permet preparar un <strong>acord directe</strong>, encara que no sempre siga possible treballar <strong>sense eixir del poble</strong>.'],
    ['Campanyes agrícoles i relleu generacional', `Una <strong>campanya agrícola</strong> de <strong>collita o poda</strong> necessita <strong>dates, durada, transport</strong> i <strong>condicions clares</strong>. El <strong>relleu generacional</strong> també pot significar <strong>aprendre un ofici</strong> al costat de <strong>qui es jubila</strong> i donar continuïtat a una explotació o taller. El ${link(sources.relleu, 'MAPA documenta les mesures per a incorporar joves al sector agrari')}; publicar una oferta <strong>no equival a obtindre una ajuda</strong>. Transmetre coneixements demana temps i acompanyament.`],
    ['Cures, serveis i condicions sostenibles', `Les <strong>cures a persones majors</strong>, l’<strong>atenció a la infància</strong> i els <strong>serveis quotidians</strong> sostenen la vida al poble. L’${link(sources.rural, 'informe de l’Oficina C del Congrés sobre desenvolupament rural')} explica les dificultats d’accés a cures i els seus efectes sobre l’ocupació. Una oferta ha de dir <strong>tasques, horari, salari i desplaçaments</strong>; la <strong>confiança veïnal</strong> acompanya, però no substituïx, els <strong>drets laborals</strong> ni les <strong>qualificacions necessàries</strong>.`]
  ],
  es: ['Trabajo', 'Trabajo digno y oficios que mantienen vivo el pueblo', 'Conectamos a quien busca trabajo con quien necesita ayuda. Los ejemplos describen necesidades rurales, no vacantes confirmadas.',
    ['Conectar el talento local', 'La <strong>construcción, electricidad, fontanería y reparaciones</strong> sostienen la vida cotidiana. Una oferta útil indica <strong>lugar, tareas, horario y remuneración</strong>. El contacto directo entre personas facilita el encuentro, sin prometer que toda la actividad se realizará dentro del municipio.'],
    ['Campañas agrícolas y relevo generacional', `Una <strong>campaña de cosecha o poda</strong> necesita fechas, duración, transporte y condiciones claras. El relevo también permite aprender junto a quien se jubila y mantener una explotación o taller. El ${link(sources.relleu, 'MAPA documenta las medidas de incorporación de jóvenes al sector agrario')}; publicar una oferta no concede ninguna ayuda.`],
    ['Cuidados y servicios con buenas condiciones', `Los <strong>cuidados de mayores y de la infancia</strong> son esenciales. El ${link(sources.rural, 'informe de la Oficina C del Congreso sobre desarrollo rural')} explica las barreras de acceso a cuidados y su relación con el empleo. Las ofertas deben aclarar <strong>tareas, horario, salario y desplazamientos</strong>. La confianza vecinal acompaña los derechos laborales y las cualificaciones necesarias, sin sustituirlos.`]
  ],
  en: ['Work', 'Decent work and skills that keep villages alive', 'Connecting people seeking work with people who need help. These examples describe rural needs, not confirmed vacancies.',
    ['Connecting local skills', '<strong>Building, electrical work, plumbing and repairs</strong> keep everyday life running. A useful listing states the <strong>location, tasks, hours and pay</strong>. Direct contact can bring neighbours together, without promising that every job can take place within the village.'],
    ['Farm seasons and the next generation', `A <strong>harvest or pruning season</strong> needs clear dates, duration, transport and conditions. Succession can include learning from someone approaching retirement and keeping a farm or workshop open. ${link(sources.relleu, 'Spain’s agriculture ministry documents support for young farmers')}; posting a job does not award a grant.`],
    ['Care and services with fair conditions', `<strong>Elder care and childcare</strong> sustain village life. The ${link(sources.rural, 'Spanish Parliament’s Office C report on rural development')} describes barriers to care services and their effects on employment. Listings should explain <strong>tasks, hours, pay and travel</strong>. Neighbourly trust goes alongside employment rights and required qualifications; it does not replace them.`]
  ],
  eu: ['Lana', 'Herriak bizirik mantentzen dituzten lan duinak eta lanbideak', 'Lana bilatzen dutenak eta laguntza behar dutenak harremanetan jartzen ditugu. Adibideek landa beharrak azaltzen dituzte, ez baieztatutako lanpostu hutsak.',
    ['Tokiko gaitasunak lotzea', '<strong>Eraikuntzak, elektrizitateak, iturgintzak eta konponketek</strong> eguneroko bizitza sostengatzen dute. Iragarki erabilgarri batek <strong>lekua, zereginak, ordutegia eta ordainsaria</strong> adierazten ditu. Harreman zuzenak auzokoak lotzen ditu, lan oro herrian bertan egin ahal izango dela agindu gabe.'],
    ['Nekazaritza kanpainak eta belaunaldi erreleboa', `<strong>Uzta edo inausketa kanpainek</strong> data, iraupen, garraio eta baldintza argiak behar dituzte. Erretiroa hartuko duen pertsonarekin ikasteak ustiategi edo lantegi bati jarraipena eman diezaioke. ${link(sources.relleu, 'MAPAk gazteak nekazaritzan sartzeko neurriak dokumentatzen ditu')}; iragarkia argitaratzeak ez du dirulaguntzarik ematen.`],
    ['Zaintza eta zerbitzuak baldintza duinetan', `<strong>Adinekoen eta haurren zaintzak</strong> herriko bizitza sostengatzen du. ${link(sources.rural, 'Espainiako Kongresuko C Bulegoaren landa garapeneko txostenak')} zaintza zerbitzuetarako oztopoak eta enpleguan dituzten ondorioak azaltzen ditu. Eskaintzek <strong>zereginak, ordutegia, soldata eta joan etorriak</strong> argitu behar dituzte. Auzokoen konfiantzak ez ditu lan eskubideak edo beharrezko kualifikazioak ordezkatzen.`]
  ],
  gl: ['Traballo', 'Traballo digno e oficios que manteñen viva a aldea', 'Conectamos a quen busca traballo con quen precisa axuda. Os exemplos describen necesidades rurais, non vacantes confirmadas.',
    ['Conectar o talento local', 'A <strong>construción, electricidade, fontanería e reparacións</strong> sosteñen a vida diaria. Unha oferta útil indica <strong>lugar, tarefas, horario e remuneración</strong>. O contacto directo facilita o encontro, sen prometer que toda a actividade se fará dentro do municipio.'],
    ['Campañas agrarias e relevo xeracional', `Unha <strong>campaña de colleita ou poda</strong> precisa datas, duración, transporte e condicións claras. O relevo pode incluír aprender de quen se xubila e manter unha explotación ou obradoiro. O ${link(sources.relleu, 'MAPA documenta as medidas para incorporar a mocidade ao sector agrario')}; publicar unha oferta non concede ningunha axuda.`],
    ['Coidados e servizos con boas condicións', `Os <strong>coidados das persoas maiores e da infancia</strong> sosteñen a vida na aldea. O ${link(sources.rural, 'informe da Oficina C do Congreso sobre desenvolvemento rural')} explica as barreiras de acceso aos coidados e os seus efectos no emprego. Cómpre aclarar <strong>tarefas, horario, salario e desprazamentos</strong>. A confianza veciñal acompaña os dereitos laborais e as cualificacións necesarias, sen substituílos.`]
  ]
};

const dossier = {
 ca: {
  date: '5 de novembre de 2026', current: 'Balanç verificat · producció R1–R3', prepared: 'Preparat als kits · pendent d’integració', pending: 'Què falta demostrar',
  prod: `Els tres nodes i punts d’accés (${link('https://socdepoble.org', '<strong>socdepoble.org</strong>')}, ${link('https://gentdelatorre.net', '<strong>gentdelatorre.net</strong>')} i el pilot ${link('https://socdepoble.cat', '<strong>socdepoble.cat</strong>')}) tenen desplegat el <strong>COMMIT R1–R3</strong> amb <strong>8 àmbits de publicació</strong>. L’estudi de <strong>Mastodon en 10 eixos</strong> és documentació feta; no equival a una <strong>xarxa federada completa</strong>.`,
  db: `El Node 0 disposa de <strong>PostgreSQL 17.11</strong>, <strong>40 taules</strong> en el recompte públic i <strong>32 documents públics persistits</strong>, segons l’auditoria del 5 de novembre. La seua ${link('https://socdepoble.cat/api/v1/node0/status', '<strong>API pública d’estat</strong>')} permet comprovar-ne l’estat actual. La <strong>SPA continua amb Supabase</strong>: tindre esta base pròpia no significa que totes les pantalles ja la facen servir. L’<strong>entrada de persones</strong> i les <strong>escriptures</strong> de l’API pròpia continuen <strong>desactivades</strong>.`,
  bridge: `El compte ${link('https://mastodont.cat/@depoble', '<strong>@depoble@mastodont.cat</strong>')} i l’<strong>autorització d’eixida</strong> estan <strong>validats</strong>. L’auditoria no acredita cap <strong>tut enviat</strong> ni una <strong>prova completa</strong> de seguiment, resposta i entrega entre servidors. La publicació externa necessita <strong>conformitat humana</strong>.`,
  kit: 'Els <strong>kits R8 i R9 de resiliència</strong> estan <strong>segellats</strong> i <strong>provats en còpia aïllada</strong>, <strong>pendents de revisió i integració</strong>. Inclouen millores de <strong>conformitat</strong>, autenticació, mirall xifrat, espera de PostgreSQL i reintents de la bústia d’eixida. El suplement editorial <strong>v1.2.0</strong> aporta les tres pestanyes territorials, l’Aplec 2023 i este dossier; preparar un kit no el desplega.',
  todo: 'La protecció <strong>3-2-1 continua incompleta</strong>: el <strong>mirall xifrat</strong> està <strong>configurat</strong>, però falta acreditar una <strong>còpia externa de la clau</strong> privada (<strong>R-5</strong>) i una <strong>restauració completa</strong> en una <strong>màquina neta</strong>. També queden l’activació controlada de comptes i escriptures, la connexió de la SPA a l’API pròpia, les entregues federades reals i la validació reproduïble amb Nix. Les proves sintètiques no tanquen estos pendents.',
  grant: 'La candidatura <strong>NLnet 2026-08-1a6</strong>, de <strong>50.000 € i 1.000 hores</strong>, no va passar la <strong>primera selecció</strong>; <strong>no hi ha finançament concedit</strong>. La resposta enviada el <strong>4 de novembre</strong> <strong>no acredita la reobertura</strong> de la sol·licitud.',
  guideTitle: 'Explicat en paraules senzilles per a qualsevol veí o veïna del poble',
  guideIntro: '<strong>Sóc de Poble</strong> és com la <strong>plaça major i el rebost comú</strong> dels nostres pobles dins del mòbil o de l’ordinador, <strong>sense anuncis molestos ni comissions</strong> i sense cap gran empresa de fora manant sobre les nostres dades. Des del <a href="/notes"><strong>Bloc de Notes</strong></a> qualsevol persona major, jove, associació o ajuntament pot publicar en <strong>els 8 àmbits essencials</strong> de la vida rural: el <a href="/mur"><strong>Mur del Poble</strong></a>, el <a href="/mercat"><strong>Mercat Local</strong></a>, el <a href="/calendari"><strong>Calendari i Agenda</strong></a>, el <a href="/mapa">Mapa del Territori</a>, Compartir Cotxe, Animalets, <a href="/page/treball">Treball</a> i <a href="/page/habitatge">Habitatge</a>.',
  guideTabsTitle: 'Les tres pestanyes dels pobles, la biblioteconomia i el respecte als escuts municipals',
  guideTabs: 'Quan entres a la fitxa de qualsevol poble a <a href="/pobles">Pobles</a>, la informació s’ordena en <strong>tres pestanyes molt clares</strong>: <strong>«Tot»</strong>, <strong>«Gent del poble»</strong> i <strong>«Xarxa»</strong> (el que publiquen pobles germans). Les cròniques històriques es classifiquen amb un <strong>sistema de biblioteconomia</strong> que separa pobles i comarques de les <strong>6 grans categories temàtiques</strong>. Per respecte institucional, les fitxes de pobles i comunitats veïnals com <strong>Gent de la Torre</strong> o Benillup mostren sempre <strong>fotografies reals del paisatge i patrimoni</strong>, i mai escuts heràldics oficials, reservats exclusivament als ajuntaments.',
  guideNodeTitle: 'Què és el servidor de l’habitació i com protegim la memòria del poble',
  guideNode: `En lloc de deixar la història del poble només en ordinadors d’empreses llunyanes, el <a href="/page/node-zero"><strong>Node 0 · Mac mini M4</strong></a> (${link('https://socdepoble.cat', '<strong>socdepoble.cat</strong>')}) funciona com un <strong>servidor menut i silenciós</strong> al mateix poble que gasta menys llum que una bombeta. La memòria col·lectiva s’hi prepara sota la <strong>regla 3-2-1 en tres llocs</strong> (servidor del poble, disc diari local i <strong>mirall xifrat al núvol</strong>), mentre cada publicació cap a la xarxa lliure passa per una <strong>safata de conformitat humana</strong> on una persona del poble revisa i autoritza què s’envia.`,
  titles: ['Nodes i Fedivers', 'Candidatura Europea NLnet · NGI Fediversity', 'Node 0 · Mac mini M4: el servidor de l’habitació'],
  subtitle: 'Què funciona, què està preparat i què queda pendent',
  lead: 'Un balanç datat dels serveis del poble. Cada avanç distingix producció, proves locals i treball pendent.',
  version: 'v1.2.0 · suplement pendent d’integració',
  map: ['Publicar al Mapa', 'Compartir llocs útils del nostre territori', 'Marca camins, fonts, patrimoni i punts de trobada amb cura per la privacitat.', 'Situar-nos al territori', 'Un avís d’un camí tallat o una font pot ajudar el veïnat. Publica una ubicació comprovada i una descripció útil.', 'Privacitat abans de publicar', 'Les fotos de portada conserven per defecte la ubicació i la data; pots llevar-les desmarcant «Conserva la ubicació i la data de la foto». Les imatges dins del text es netegen sempre.', 'Un mapa públic', 'El punt publicat es pot vore des d’altres pàgines i pobles. No assenyales domicilis privats sense permís.']
 },
 es: {
  date: '5 de noviembre de 2026', current: 'Balance verificado · producción R1–R3', prepared: 'Preparado en kits · pendiente de integración', pending: 'Qué falta demostrar',
  prod: `El <strong>COMMIT R1–R3</strong> está desplegado en ${link('https://socdepoble.org', 'socdepoble.org')}, ${link('https://gentdelatorre.net', 'gentdelatorre.net')} y ${link('https://socdepoble.cat', 'socdepoble.cat')}. El editor ofrece <strong>8 ámbitos de publicación</strong>. El estudio de <strong>Mastodon en 10 ejes</strong> es documentación terminada, sin acreditar una red federada completa.`,
  db: `El Node 0 dispone de <strong>PostgreSQL 17.11</strong>, <strong>40 tablas</strong> en el recuento público y <strong>32 documentos públicos persistidos</strong>, según la auditoría del 5 de noviembre. Su ${link('https://socdepoble.cat/api/v1/node0/status', 'API pública de estado')} permite consultar la situación actual. La <strong>SPA sigue con Supabase</strong>; las cuentas y escrituras de personas en la API propia siguen desactivadas.`,
  bridge: `La cuenta ${link('https://mastodont.cat/@depoble', '<strong>@depoble@mastodont.cat</strong>')} y la autorización de salida están validadas. No consta ningún mensaje enviado ni una prueba completa de seguimiento, respuesta y entrega entre servidores. La publicación externa requiere conformidad humana.`,
  kit: 'Los <strong>kits R8 y R9 de resiliencia</strong> están sellados y probados en copia aislada, pendientes de revisión e integración. Aportan conformidad, autenticación, espejo cifrado, espera de PostgreSQL y reintentos de la bandeja de salida. El suplemento <strong>v1.2.0</strong> prepara las tres pestañas territoriales, el Aplec 2023 y este dossier; un kit preparado no está desplegado.',
  todo: 'La protección <strong>3-2-1 sigue incompleta</strong>: existe un espejo cifrado configurado, pero falta acreditar la custodia externa de la clave privada (<strong>R-5</strong>) y una restauración completa en una máquina limpia. Quedan la activación controlada de cuentas y escrituras, la conexión de la SPA a la API propia, las entregas federadas reales y la validación reproducible con Nix. Las pruebas sintéticas no resuelven esos pendientes.',
  grant: 'La candidatura <strong>NLnet 2026-08-1a6</strong>, de <strong>50.000 € y 1.000 horas</strong>, no superó la primera selección; <strong>no hay financiación concedida</strong>. La respuesta enviada el 4 de noviembre no acredita la reapertura.',
  guideTitle: 'Explicado con palabras sencillas para cualquier vecino o vecina del pueblo',
  guideIntro: '<strong>Sóc de Poble</strong> es como la <strong>plaza mayor y la despensa común</strong> de nuestros pueblos en el móvil o el ordenador, <strong>sin anuncios molestos ni comisiones</strong>. Desde el <a href="/notes"><strong>Bloc de Notas</strong></a> cualquier persona mayor, joven, asociación o ayuntamiento puede publicar en <strong>los 8 ámbitos esenciales</strong> de la vida rural: <a href="/mur"><strong>Muro</strong></a>, <a href="/mercat"><strong>Mercado</strong></a>, <a href="/calendari"><strong>Calendario</strong></a>, <a href="/mapa"><strong>Mapa</strong></a>, Compartir Coche, Animales, <a href="/page/treball"><strong>Trabajo</strong></a> y <a href="/page/habitatge"><strong>Vivienda</strong></a>.',
  guideTabsTitle: 'Las tres pestañas de los pueblos, la biblioteconomía y el respeto a los escudos municipales',
  guideTabs: 'En la ficha de cada pueblo en <a href="/pobles"><strong>Pueblos</strong></a>, la información se ordena en <strong>tres pestañas muy claras</strong>: <strong>«Todo»</strong>, <strong>«Gente del pueblo»</strong> y <strong>«Red»</strong>. Además, clasificamos las crónicas históricas separando <strong>pueblos y comarcas</strong> de las <strong>6 grandes categorías temáticas</strong>, y las fichas vecinales como <strong>Gent de la Torre</strong> usan siempre <strong>fotografías reales del paisaje y patrimonio</strong>, reservando los escudos heráldicos oficiales exclusivamente a los ayuntamientos.',
  guideNodeTitle: 'Qué es el servidor de la habitación y cómo protegemos la memoria del pueblo',
  guideNode: `El <a href="/page/node-zero"><strong>Node 0 · Mac mini M4</strong></a> (${link('https://socdepoble.cat', '<strong>socdepoble.cat</strong>')}) es un <strong>servidor pequeño y silencioso</strong> en el propio pueblo que consume menos luz que una bombilla, diseñado para proteger la memoria colectiva bajo la <strong>regla 3-2-1</strong> y con una <strong>bandeja de conformidad humana</strong> antes de enviar noticias al exterior.`,
  titles: ['Nodos y Fediverso', 'Candidatura europea NLnet · NGI Fediversity', 'Node 0 · Mac mini M4: el servidor de la habitación'], subtitle: 'Qué funciona, qué está preparado y qué queda pendiente', lead: 'Un balance fechado de los servicios del pueblo que distingue producción, pruebas locales y trabajo pendiente.', version: 'v1.2.0 · suplemento pendiente de integración',
  map: ['Publicar en el Mapa', 'Compartir lugares útiles del territorio', 'Sitúa caminos, fuentes, patrimonio y puntos de encuentro cuidando la privacidad.', 'Situarnos en el territorio', 'Un aviso de un camino cortado o una fuente puede ayudar al vecindario. Publica una ubicación comprobada y una descripción útil.', 'Privacidad antes de publicar', 'Las fotos de portada conservan por defecto la ubicación y la fecha; puedes quitarlas desmarcando «Conserva la ubicación y la fecha de la foto». Las imágenes dentro del texto se limpian siempre.', 'Un mapa público', 'El punto publicado puede verse desde otras páginas y pueblos. No señales domicilios privados sin permiso.']
 },
 en: {
  date: '5 November 2026', current: 'Verified balance · R1–R3 in production', prepared: 'Prepared in kits · integration pending', pending: 'What remains to be demonstrated',
  prod: `<strong>COMMIT R1–R3</strong> is deployed at ${link('https://socdepoble.org', 'socdepoble.org')}, ${link('https://gentdelatorre.net', 'gentdelatorre.net')} and ${link('https://socdepoble.cat', 'socdepoble.cat')}. The editor has <strong>8 publication areas</strong>. The <strong>10-part Mastodon study</strong> is completed documentation, rather than evidence of a fully operating federated network.`,
  db: `Node 0 has <strong>PostgreSQL 17.11</strong>, <strong>40 tables</strong> in its public count and <strong>32 persisted public documents</strong>, according to the 5 November audit. Its ${link('https://socdepoble.cat/api/v1/node0/status', 'public status API')} exposes current status. The <strong>SPA still uses Supabase</strong>; user accounts and writes through the independent API remain disabled.`,
  bridge: `The ${link('https://mastodont.cat/@depoble', '<strong>@depoble@mastodont.cat</strong>')} account and outbound authorization are verified. No outgoing post or complete follow, reply and delivery test between servers is recorded. External publication needs human approval.`,
  kit: 'The <strong>R8 and R9 resilience kits</strong> are sealed and tested in an isolated copy, awaiting review and integration. They cover conformance, authentication, encrypted mirroring, PostgreSQL startup waits and outbox retries. The <strong>v1.2.0</strong> supplement prepares the three territorial tabs, Aplec 2023 and this dossier; preparing a kit does not deploy it.',
  todo: '<strong>3-2-1 protection remains incomplete</strong>: an encrypted mirror is configured, but external custody of the private key (<strong>R-5</strong>) and a complete restore on a clean machine remain unverified. Controlled account and write activation, SPA connection to the independent API, real federated deliveries and reproducible Nix validation are also pending. Synthetic tests do not complete these steps.',
  grant: 'The <strong>NLnet 2026-08-1a6</strong> application for <strong>€50,000 and 1,000 hours</strong> did not pass the first selection; <strong>no funding was awarded</strong>. The reply sent on 4 November does not establish that the application reopened.',
  guideTitle: 'Explained in plain words for every neighbour in the village',
  guideIntro: '<strong>Sóc de Poble</strong> works like the <strong>village square and shared pantry</strong> on your phone or computer, <strong>with no ads or commissions</strong>. From the <a href="/notes"><strong>Notebook</strong></a> any elder, young person, association or town council can publish across <strong>8 essential areas</strong> of rural life: <a href="/mur"><strong>Village Wall</strong></a>, <a href="/mercat"><strong>Local Market</strong></a>, <a href="/calendari"><strong>Calendar</strong></a>, <a href="/mapa"><strong>Map</strong></a>, Carpooling, Animals, <a href="/page/treball"><strong>Work</strong></a> and <a href="/page/habitatge"><strong>Housing</strong></a>.',
  guideTabsTitle: 'The three village tabs, library classification and respect for municipal coats of arms',
  guideTabs: 'Every village page in <a href="/pobles"><strong>Villages</strong></a> is organised into <strong>three clear tabs</strong>: <strong>“All”</strong>, <strong>“Village people”</strong> and <strong>“Network”</strong>. Historical chronicles follow a <strong>library classification system</strong> separating <strong>villages and counties</strong> from <strong>6 thematic categories</strong>, and community cards like <strong>Gent de la Torre</strong> always display <strong>real landscape and heritage photos</strong> rather than official municipal coats of arms, which are reserved exclusively for town halls.',
  guideNodeTitle: 'What the room server is and how we protect village memory',
  guideNode: `<a href="/page/node-zero"><strong>Node 0 · Mac mini M4</strong></a> (${link('https://socdepoble.cat', '<strong>socdepoble.cat</strong>')}) is a <strong>quiet, low-power local server</strong> in the village designed to safeguard collective memory under the <strong>3-2-1 backup rule</strong>, with a <strong>human approval tray</strong> before any post is federated outward.`,
  titles: ['Nodes and the Fediverse', 'European application NLnet · NGI Fediversity', 'Node 0 · Mac mini M4: the server in the room'], subtitle: 'What works, what is prepared and what remains pending', lead: 'A dated account of village services, distinguishing production, local tests and pending work.', version: 'v1.2.0 · supplement awaiting integration',
  map: ['Publish on the Map', 'Sharing useful places in our area', 'Locate paths, springs, heritage and meeting points with care for privacy.', 'Finding our place', 'A closed path or a useful spring can help neighbours. Publish a checked location and a useful description.', 'Privacy before publication', 'Cover photos retain location and date by default; remove them by unchecking “Keep photo location and date”. Images within the text are always cleaned.', 'A public map', 'A published point can be seen from other pages and villages. Do not mark private homes without permission.']
 },
 eu: {
  date: '2026ko azaroaren 5a', current: 'Egiaztatutako balantzea · R1–R3 produkzioan', prepared: 'Kitetan prestatuta · integratzeko zain', pending: 'Zer falta da frogatzeko',
  prod: `<strong>R1–R3 COMMITa</strong> ${link('https://socdepoble.org', 'socdepoble.org')}, ${link('https://gentdelatorre.net', 'gentdelatorre.net')} eta ${link('https://socdepoble.cat', 'socdepoble.cat')} guneetan hedatuta dago. Editoreak <strong>8 argitalpen eremu</strong> ditu. <strong>Mastodonen 10 ardatzeko azterlana</strong> amaitutako dokumentazioa da; ez du federazio osoa martxan dagoela frogatzen.`,
  db: `Node 0k <strong>PostgreSQL 17.11</strong>, zenbaketa publikoan <strong>40 taula</strong> eta <strong>32 dokumentu publiko iraunkor</strong> ditu, azaroaren 5eko auditoriaren arabera. ${link('https://socdepoble.cat/api/v1/node0/status', 'Egoeraren API publikoak')} egungo egoera erakusten du. <strong>SPAk Supabase erabiltzen jarraitzen du</strong>; API propioko erabiltzaileen kontuak eta idazketak desaktibatuta daude.`,
  bridge: `${link('https://mastodont.cat/@depoble', '<strong>@depoble@mastodont.cat</strong>')} kontua eta irteerako baimena egiaztatuta daude. Ez dago bidalitako mezuen edo zerbitzarien arteko jarraipen, erantzun eta entrega proba osoaren ebidentziarik. Kanpoko argitalpenak giza onespena behar du.`,
  kit: '<strong>R8 eta R9 erresilientzia kitak</strong> zigilatuta eta kopia isolatuan probatuta daude, berrikusteko eta integratzeko zain. Adostasuna, autentifikazioa, ispilu zifratua, PostgreSQL abiatzeko itxaronaldia eta irteerako berriz saiatzeak hobetzen dituzte. <strong>v1.2.0</strong> osagarriak hiru lurralde fitxak, Aplec 2023 eta dosier hau prestatzen ditu; kit bat prestatzeak ez du hedatzen.',
  todo: '<strong>3-2-1 babesa osatu gabe dago</strong>: ispilu zifratua konfiguratuta dago, baina gako pribatuaren kanpoko zaintza (<strong>R-5</strong>) eta makina garbi batean leheneratze osoa frogatu behar dira. Kontuen eta idazketen aktibazio kontrolatua, SPA API propiora lotzea, benetako entrega federatuak eta Nix bidezko balidazio erreproduzigarria ere falta dira. Proba sintetikoek ez dituzte urrats horiek amaitzen.',
  grant: '<strong>NLnet 2026-08-1a6</strong> eskaerak, <strong>50.000 € eta 1.000 ordukoa</strong>, ez zuen lehen hautaketa gainditu; <strong>ez dago emandako finantzaketarik</strong>. Azaroaren 4an bidalitako erantzunak ez du eskaera berriro ireki denik frogatzen.',
  guideTitle: 'Hitz errazetan azalduta herriko edozein bizilagunentzat',
  guideIntro: '<strong>Sóc de Poble</strong> gure herrietako <strong>plaza nagusia eta despentsa komuna</strong> bezalakoa da mugikorrean edo ordenagailuan, <strong>iragarki gogaikarririk eta komisiorik gabe</strong>. <a href="/notes"><strong>Koadernotik</strong></a> edozein adinekok, gaztek, elkartek edo udalek landa bizitzako <strong>8 eremu nagusietan</strong> argitaratu dezake: <a href="/mur"><strong>Hormak</strong></a>, <a href="/mercat"><strong>Merkatua</strong></a>, <a href="/calendari"><strong>Egutegia</strong></a>, <a href="/mapa"><strong>Mapa</strong></a>, Autoa Partekatzea, Animaliak, <a href="/page/treball"><strong>Lana</strong></a> eta <a href="/page/habitatge"><strong>Etxebizitza</strong></a>.',
  guideTabsTitle: 'Herrien hiru fitxak, bibliotekonomia eta udal armarriekiko errespetua',
  guideTabs: '<a href="/pobles"><strong>Herriak</strong></a> ataleko fitxa bakoitza <strong>hiru fitxa argitan</strong> banatzen da: <strong>«Dena»</strong>, <strong>«Herriko jendea»</strong> eta <strong>«Sarea»</strong>. Kronika historikoak <strong>herriak eta eskualdeak</strong> eta <strong>6 kategoria tematikoak</strong> bereizten dituen <strong>bibliotekonomia sistemarekin</strong> sailkatzen dira, eta <strong>Gent de la Torre</strong> bezalako komunitate fitxek beti <strong>paisaiaren eta ondarearen benetako argazkiak</strong> erabiltzen dituzte, udal armarri ofizialak udalentzat bakarrik utziz.',
  guideNodeTitle: 'Zer den gelako zerbitzaria eta nola babesten dugun herriaren memoria',
  guideNode: `<a href="/page/node-zero"><strong>Node 0 · Mac mini M4</strong></a> (${link('https://socdepoble.cat', '<strong>socdepoble.cat</strong>')}) herrian bertan dagoen <strong>zerbitzari txiki eta isila</strong> da, memoria kolektiboa <strong>3-2-1 babes arauarekin</strong> zaintzeko eta kanpora ezer bidali aurretik <strong>giza onespen erretilua</strong> bermatzeko.`,
  titles: ['Nodoak eta Fedibertsoa', 'Europako NLnet hautagaitza · NGI Fediversity', 'Node 0 · Mac mini M4: gelako zerbitzaria'], subtitle: 'Zer dabil, zer dago prestatuta eta zer falta da', lead: 'Herriko zerbitzuen datatutako balantzea, produkzioa, tokiko probak eta egiteke dagoen lana bereiziz.', version: 'v1.2.0 · integratzeko zain dagoen osagarria',
  map: ['Mapan argitaratu', 'Lurraldeko leku erabilgarriak partekatzea', 'Kokatu bideak, iturriak, ondarea eta elkarguneak pribatutasuna zainduz.', 'Lurraldean kokatzea', 'Itxitako bide baten edo iturri baten berri emateak auzokoei lagun diezaieke. Egiaztatutako kokapena eta deskribapen erabilgarria argitaratu.', 'Pribatutasuna argitaratu aurretik', 'Azaleko argazkiek kokapena eta data gordetzen dituzte lehenespenez; kendu ditzakezu argazkiaren kokapena eta data gordetzeko aukera desmarkatuz. Testu barruko irudiak beti garbitzen dira.', 'Mapa publikoa', 'Argitaratutako puntua beste orri eta herrietatik ikus daiteke. Ez markatu etxe pribaturik baimenik gabe.']
 },
 gl: {
  date: '5 de novembro de 2026', current: 'Balance verificado · produción R1–R3', prepared: 'Preparado nos kits · integración pendente', pending: 'Que falta demostrar',
  prod: `O <strong>COMMIT R1–R3</strong> está despregado en ${link('https://socdepoble.org', 'socdepoble.org')}, ${link('https://gentdelatorre.net', 'gentdelatorre.net')} e ${link('https://socdepoble.cat', 'socdepoble.cat')}. O editor ten <strong>8 ámbitos de publicación</strong>. O estudo de <strong>Mastodon en 10 eixes</strong> é documentación rematada, sen acreditar unha rede federada completa.`,
  db: `O Node 0 dispón de <strong>PostgreSQL 17.11</strong>, <strong>40 táboas</strong> no reconto público e <strong>32 documentos públicos persistidos</strong>, segundo a auditoría do 5 de novembro. A súa ${link('https://socdepoble.cat/api/v1/node0/status', 'API pública de estado')} permite consultar a situación actual. A <strong>SPA segue con Supabase</strong>; as contas e escrituras de persoas na API propia seguen desactivadas.`,
  bridge: `A conta ${link('https://mastodont.cat/@depoble', '<strong>@depoble@mastodont.cat</strong>')} e a autorización de saída están validadas. Non consta ningunha mensaxe enviada nin unha proba completa de seguimento, resposta e entrega entre servidores. A publicación externa precisa conformidade humana.`,
  kit: 'Os <strong>kits R8 e R9 de resiliencia</strong> están selados e probados nunha copia illada, pendentes de revisión e integración. Achegan conformidade, autenticación, espello cifrado, espera de PostgreSQL e reintentos da caixa de saída. O suplemento <strong>v1.2.0</strong> prepara as tres lapelas territoriais, o Aplec 2023 e este dossier; preparar un kit non o desprega.',
  todo: 'A protección <strong>3-2-1 segue incompleta</strong>: hai un espello cifrado configurado, pero falta acreditar a custodia externa da clave privada (<strong>R-5</strong>) e unha restauración completa nunha máquina limpa. Quedan a activación controlada de contas e escrituras, a conexión da SPA á API propia, as entregas federadas reais e a validación reproducible con Nix. As probas sintéticas non pechan estes pendentes.',
  grant: 'A candidatura <strong>NLnet 2026-08-1a6</strong>, de <strong>50.000 € e 1.000 horas</strong>, non superou a primeira selección; <strong>non hai financiamento concedido</strong>. A resposta enviada o 4 de novembro non acredita a reapertura.',
  guideTitle: 'Explicado con palabras sinxelas para calquera veciño ou veciña da aldea',
  guideIntro: '<strong>Sóc de Poble</strong> é como a <strong>praza maior e a despensa común</strong> das nosas aldeas no móbil ou no ordenador, <strong>sen anuncios molestos nin comisións</strong>. Desde o <a href="/notes"><strong>Caderno de Notas</strong></a> calquera persoa maior, moza, asociación ou concello pode publicar nos <strong>8 ámbitos esenciais</strong> da vida rural: <a href="/mur"><strong>Muro</strong></a>, <a href="/mercat"><strong>Mercado</strong></a>, <a href="/calendari"><strong>Calendario</strong></a>, <a href="/mapa"><strong>Mapa</strong></a>, Compartir Coche, Animais, <a href="/page/treball"><strong>Traballo</strong></a> e <a href="/page/habitatge"><strong>Vivenda</strong></a>.',
  guideTabsTitle: 'As tres lapelas das aldeas, a biblioteconomía e o respecto aos escudos municipais',
  guideTabs: 'Na ficha de cada pobo en <a href="/pobles"><strong>Pobos</strong></a>, a información ordénase en <strong>tres lapelas moi claras</strong>: <strong>«Todo»</strong>, <strong>«Xente da aldea»</strong> e <strong>«Rede»</strong>. Ademais, clasificamos as crónicas históricas separando <strong>pobos e comarcas</strong> das <strong>6 grandes categorías temáticas</strong>, e as fichas veciñais como <strong>Gent de la Torre</strong> mostran sempre <strong>fotografías reais da paisaxe e do patrimonio</strong>, reservando os escudos heráldicos oficiais exclusivamente aos concellos.',
  guideNodeTitle: 'Que é o servidor da habitación e como protexemos a memoria da aldea',
  guideNode: `O <a href="/page/node-zero"><strong>Node 0 · Mac mini M4</strong></a> (${link('https://socdepoble.cat', '<strong>socdepoble.cat</strong>')}) é un <strong>servidor pequeno e silencioso</strong> na propia aldea que consome menos luz ca unha lámpada, deseñado para protexer a memoria colectiva baixo a <strong>regra 3-2-1</strong> e cunha <strong>bandexa de conformidade humana</strong> antes de enviar novas ao exterior.`,
  titles: ['Nodos e Fediverso', 'Candidatura europea NLnet · NGI Fediversity', 'Node 0 · Mac mini M4: o servidor da habitación'], subtitle: 'Que funciona, que está preparado e que queda pendente', lead: 'Un balance datado dos servizos da aldea que distingue produción, probas locais e traballo pendente.', version: 'v1.2.0 · suplemento pendente de integración',
  map: ['Publicar no Mapa', 'Compartir lugares útiles do territorio', 'Sitúa camiños, fontes, patrimonio e puntos de encontro coidando a privacidade.', 'Situarnos no territorio', 'Un aviso dun camiño cortado ou dunha fonte pode axudar á veciñanza. Publica unha localización comprobada e unha descrición útil.', 'Privacidade antes de publicar', 'As fotos de portada conservan por defecto a localización e a data; podes retiralas desmarcando a opción de conservar a localización e a data da foto. As imaxes dentro do texto límpanse sempre.', 'Un mapa público', 'O punto publicado pode verse desde outras páxinas e aldeas. Non sinais domicilios privados sen permiso.']
 }
};

const ruralPage = (row) => ({ title: row[0], subtitle: row[1], lead: row[2], html: section('h3', row[1])+'\n      '+row.slice(3).map(s => section('h5', ...s)).join('\n      '), labels: [] });
const statusHtml = (d) => '\n      '+[
 section('h3', `${d.date} · ${d.current}`, d.prod, d.db, d.bridge),
 section('h3', d.prepared, d.kit),
 section('h3', d.pending, d.todo),
 section('h3', d.guideTitle, d.guideIntro),
 subSection(d.guideTabsTitle, d.guideTabs),
 subSection(d.guideNodeTitle, d.guideNode)
].join('\n      ');

/** Authored translations belong to the page, not the UI dictionary. Remote/custom
 * pages without translations keep their own content and original language. */
export function localitzaPagina(page, language = 'ca') {
 const translated = page?.translations?.[language];
 return translated ? { ...page, ...translated, contentLanguage: language } : page;
}

export function aplicaDossierR10(copy) {
 const originals = Object.fromEntries(['fedivers', 'fediversity', 'node-zero', 'versions', 'publicar_mapa'].map(k => [k, copy[k]]));
 for (const key of ['habitatge', 'treball', 'publicar_mapa', 'fedivers', 'fediversity', 'node-zero', 'versions']) {
  const translations = {};
  for (const [language, d] of Object.entries(dossier)) {
   let content;
   if (key === 'habitatge' || key === 'treball') content = ruralPage((key === 'habitatge' ? housing : jobs)[language]);
   else if (key === 'publicar_mapa') {
    const m = d.map;
    content = language === 'ca' ? {html:section('h3',m[1])+originals.publicar_mapa.html} : { title:m[0], subtitle:m[1], lead:m[2], labels:[], html:section('h3',m[1])+'\n      '+[3,5,7].map(i=>section('h5',m[i],m[i+1])).join('\n      ') };
   } else if (key === 'versions') {
    const entry = section('h3', `${d.date} · ${d.version}`, d.prod, d.db, d.bridge, d.kit, d.todo);
    // The old register is history in its original language; do not present it as translated.
    content = language === 'ca' ? { html:`\n      ${entry}\n      ${originals.versions.html}` } : {
     title: ({es:'Versiones',en:'Versions',eu:'Bertsioak',gl:'Versións'})[language], subtitle:d.version, lead:d.lead,
     html:`\n      ${entry}<div lang="ca">${originals.versions.html}</div>`, labels:[]
    };
   } else {
    const title = d.titles[['fedivers','fediversity','node-zero'].indexOf(key)];
    content = { title, subtitle:d.subtitle, lead:d.lead, html: statusHtml(d), labels:[] };
    if (key === 'fediversity') content.html = section('h3', 'NLnet · NGI Fediversity', `<a href="https://nlnet.nl/fediversity/" target="_blank" rel="noopener noreferrer"><img class="page-title-logo" src="/assets/uploads/ngi-fediversity-tag.svg" alt="NGI Fediversity" width="2040" height="503" /></a>`, d.grant)+content.html;
    // The detailed Valencian dossier remains readable after its dated update.
    if (language === 'ca') content = { lead:key === 'fediversity' ? originals[key].lead : d.lead, html:statusHtml(d)+ (key==='fediversity'?section('h3','Candidatura NLnet · estat de la sol·licitud',d.grant):'') + actualitzaDossierAnterior(originals[key].html) };
   }
   translations[language] = content;
  }
  Object.assign(copy[key], translations.ca, { translations, contentLanguage:'ca' });
 }
}

function actualitzaDossierAnterior(html) {
 const paragraphs = html.replace(/<(p|li)>(.*?)<\/\1>/g, (whole, tag, body) => {
  const text = body.replace(/<[^>]+>/g, '');
  if (text.startsWith('Posar en servei el pilot independent del Node 0 amb base de dades pròpia')) {
   return `<${tag}>La <strong>base PostgreSQL 17.11 i l’API pròpia</strong> ja funcionen al Node 0. Falta <strong>connectar-hi la SPA</strong>, activar comptes i escriptures amb permisos comprovats i mesurar la càrrega real del servei i el consum elèctric. La mida de tota la màquina no és el mínim necessari per a un poble.</${tag}>`;
  }
  return whole;
 });
 return paragraphs
 .replace(/sense garantia de disponibilitat ni base de dades (?:independent|pròpia) encara\.?/g, 'sense garantia de disponibilitat; PostgreSQL propi ja està instal·lat, mentre la SPA continua amb Supabase.')
 .replace(/no té garantia de disponibilitat i que <strong>encara no acredita<\/strong> una base de dades independent fora del Supabase compartit/g, 'no té garantia de disponibilitat; <strong>ja té PostgreSQL propi</strong> per a l’API, amb la SPA encara connectada a Supabase')
 .replace(/Hui hi ha <strong>un sol servidor<\/strong> de dades, el <strong>Supabase<\/strong> de Sóc de Poble\./g, 'La SPA usa el <strong>Supabase</strong> de Sóc de Poble; l’API pròpia del Node 0 ja té <strong>PostgreSQL 17.11</strong>, encara sense comptes ni escriptures de persones activats.')
 .replace(/Hui continuen al <strong>Supabase de Sóc de Poble<\/strong>, mentre el <strong>pilot independent<\/strong> es prepara i es verifica\./g, 'La SPA continua amb <strong>Supabase</strong>. En paral·lel, l’<strong>API pròpia del Node 0</strong> ja persistix documents en PostgreSQL; encara cal activar-ne l’ús complet per les pantalles.')
 .replace(/la base de dades pròpia, els dominis i la interoperabilitat remota continuen sent condicions a demostrar/g, 'la connexió de la SPA a la base pròpia i la interoperabilitat remota continuen sent condicions a demostrar')
 .replace(/mentre continua <strong>en evolució<\/strong> cap a un <strong>node independent<\/strong> amb base de dades pròpia darrere del <strong>port neutral<\/strong>/g, 'ja disposa d’<strong>API amb PostgreSQL propi</strong> i continua <strong>en evolució</strong> cap a l’ús independent des de tota la SPA darrere del <strong>port neutral</strong>');
}
